import struct

with open("{TARGET}", 'rb') as f:
    binary_data = f.read()

print("Searching for references to the strings 'Correct!' and 'Wrong!'...")

# Search for references to these string offsets
for code_offset in range(0x97d0, 0x97d0 + 0x39244 - 7):
    # Check if it's a lea instruction with RIP-relative addressing
    if binary_data[code_offset] == 0x48 and binary_data[code_offset+1] == 0x8d:
        modrm = binary_data[code_offset+2]
        # Check for RIP-relative (mod=00, r/m=101, with REX.W prefix)
        if (modrm & 0xc7) == 0x05:
            rel = struct.unpack('<i', binary_data[code_offset+3:code_offset+7])[0]
            target = (code_offset + 7) + rel  # RIP-relative calculation
            if target == 0x6a9:
                print(f"Found 'Correct!' reference at file offset {hex(code_offset)}")
            if target == 0x6b3:
                print(f"Found 'Wrong!' reference at file offset {hex(code_offset)}")

# Let's also search for direct byte patterns of these addresses
# as immediate values or data
for i in range(len(binary_data) - 4):
    val = struct.unpack('<I', binary_data[i:i+4])[0]
    if val == 0x6a9 or val == 0x6b3 or val == 0x4006a9 or val == 0x4006b3:
        print(f"Found potential reference at {hex(i)}: {hex(val)}")
